// ===== Competitors & trends from Google News RSS =====
const QUERIES = {
  "Calo": "Calo UAE meal plan",
  "Kcal": "Kcal Dubai healthy",
  "Low Calories": "\"Low Calories\" UAE restaurant",
  "Market trends": "healthy food delivery Dubai OR UAE meal plan trend"
};
const decode=s=>s.replace(/<!\[CDATA\[|\]\]>/g,"").replace(/&amp;/g,"&").replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&lt;/g,"<").replace(/&gt;/g,">").trim();
const out={}; const cutoff=Date.now()-30*864e5;
for(const [name,q] of Object.entries(QUERIES)){
  try{
    const url="https://news.google.com/rss/search?q="+encodeURIComponent(q+" when:30d")+"&hl=en-AE&gl=AE&ceid=AE:en";
    const xml=await this.helpers.httpRequest({url, method:"GET", returnFullResponse:false, json:false});
    const items=[...String(xml).matchAll(/<item>([\s\S]*?)<\/item>/g)].map(m=>{
      const g=t=>{const r=m[1].match(new RegExp("<"+t+"[^>]*>([\\s\\S]*?)</"+t+">"));return r?decode(r[1]):"";};
      return {title:g("title"), date:g("pubDate"), source:g("source"), link:g("link")};
    }).filter(i=>Date.parse(i.date)>=cutoff).sort((a,b)=>Date.parse(b.date)-Date.parse(a.date)).slice(0,5);
    out[name]=items;
  }catch(e){ out[name]=[{error:String(e.message||e)}]; }
}
